#!/usr/bin/env python3
"""Generate the Prometheus Operator PrometheusRule from the promtool-tested rule file.

Usage: sync-prometheusrule.py [--check]
--check exits non-zero if the committed manifest is out of date (used by check-all.sh).
"""

import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "monitoring/prometheus/rules/platewise.rules.yml"
TARGET = ROOT / "deploy/k8s/components/monitoring/prometheusrule.yaml"
HEADER = (
    "# GENERATED by scripts/sync-prometheusrule.py from monitoring/prometheus/rules/platewise.rules.yml\n"
    "# (the promtool-tested copy). Edit the source file, then re-run the script.\n"
)


class IndentedDumper(yaml.SafeDumper):
    """Indent block sequences under their key, matching the repo's yamllint style."""

    def increase_indent(self, flow=False, indentless=False):
        return super().increase_indent(flow, False)


def _str(dumper, value):
    style = "|" if "\n" in value else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", value, style=style)


IndentedDumper.add_representer(str, _str)


def render() -> str:
    groups = [g for g in yaml.safe_load(SOURCE.read_text())["groups"] if g["name"].startswith("platewise.")]
    doc = {
        "apiVersion": "monitoring.coreos.com/v1",
        "kind": "PrometheusRule",
        "metadata": {"name": "platewise", "labels": {"release": "kube-prometheus-stack"}},
        "spec": {"groups": groups},
    }
    return HEADER + yaml.dump(doc, Dumper=IndentedDumper, sort_keys=False, width=200)


def main() -> int:
    wanted = render()
    if "--check" in sys.argv:
        if TARGET.read_text() != wanted:
            print(f"{TARGET.relative_to(ROOT)} is stale: run scripts/sync-prometheusrule.py", file=sys.stderr)
            return 1
        print("PrometheusRule is in sync with the promtool-tested rules")
        return 0
    TARGET.write_text(wanted)
    print(f"wrote {TARGET.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
